Bash(powershell -Command "
\\$content = Get-Content 'D:\\ec\\tengxun\\插件初始化.mhtml' -Encoding UTF8 -Raw
\\$idx = \\$content.IndexOf\('<body'\)
if \(\\$idx -lt 0\) { \\$idx = \\$content.IndexOf\('<div'\) }
if \(\\$idx -ge 0\) {
    \\$body = \\$content.Substring\(\\$idx, [Math]::Min\(80000, \\$content.Length - \\$idx\)\)
    \\$cleaned = [regex]::Replace\(\\$body, '<[^>]+>', ' '\)
    \\$cleaned = \\$cleaned.Replace\('&nbsp;', ' '\)
    \\$cleaned = \\$cleaned.Replace\('&lt;', '<'\)
    \\$cleaned = \\$cleaned.Replace\('&gt;', '>'\)
    \\$cleaned = \\$cleaned.Replace\('&amp;', '&'\)
    \\$lines = \\$cleaned -split '\\n' | ForEach-Object { \\$_.Trim\(\) } | Where-Object { \\$_.Length -gt 5 }
    \\$lines | Select-Object -Skip 80 -First 80 | ForEach-Object { Write-Output \\$_.Trim\(\) }
}
")

